// CSV export of the report rows (RFC 4180 quoting, "\n" line endings).

const NEEDS_QUOTES = /[",\r\n]/

const field = (value) => {
  const text = value === null || value === undefined ? '' : String(value)
  return NEEDS_QUOTES.test(text) ? `"${text.replaceAll('"', '""')}"` : text
}

const line = (values) => `${values.map(field).join(',')}\n`

export const toCsv = (rows) => {
  if (rows.length === 0) return ''
  const columns = Object.keys(rows[0])
  const body = rows.map((row) => line(columns.map((column) => row[column])))
  return line(columns) + body.join('')
}

