// Revenue of each region, in the order the regions first appear in the rows.
// Totals are kept in a Map so region names such as "constructor" or
// "__proto__" are ordinary keys, not Object.prototype members.

export const byRegion = (rows) => {
  const totals = new Map()
  for (const row of rows) {
    totals.set(row.region, (totals.get(row.region) ?? 0) + revenue(row))
  }
  return Object.fromEntries(totals)
}
"}

